insert into public.programs ("id", "name", "kind", "group", "summary", "who", "amount", "opens", "closes", "rolling", "timing_note", "how_to_apply", "url", "source_url", "region", "last_verified", "verified_by") values
  ('acme-elevate', 'Elevate (City of Austin ACME FY27)', 'grant', 'City of Austin ACME FY27', 'City of Austin funding for arts organizations, individual artists, and creative businesses producing public art. KUT reported about $11 million.', '["Arts organizations, individual artists, and creative businesses producing public art","18 or older","Live or based in the Austin-Round Rock MSA for the grant term","Public activities in Austin or the ETJ; HOT tourism rules apply","One application per program per applicant entity","Not a full-time City of Austin / ACME employee"]'::jsonb, 'About $11 million in total (as reported by KUT)', null, '2026-08-18T18:59:00-05:00', false, 'The FY27 round closed 6:59pm on August 18, 2026. Late applications were not accepted.', 'Complete the Universal Program Eligibility Form, then the program application. Portal help: ApplicationHelp@thelongcenter.org. Program questions: CulturalArts@AustinTexas.gov. Office hours Tuesdays 10am-noon.', 'https://www.austintexas.gov/arts-culture/funding-programs', null, 'Austin', '2026-08-15', 'starter list'),
  ('acme-thrive', 'Thrive (City of Austin ACME FY27)', 'grant', 'City of Austin ACME FY27', 'City of Austin funding for local arts nonprofits. KUT reported about $3 million.', '["Local arts nonprofits","Universal program notes apply: Austin-Round Rock MSA, public activities in Austin or the ETJ, one application per program per applicant entity"]'::jsonb, 'About $3 million in total (as reported by KUT)', null, '2026-08-18T18:59:00-05:00', false, 'The FY27 round closed 6:59pm on August 18, 2026. Late applications were not accepted.', 'Complete the Universal Program Eligibility Form, then the program application. Portal help: ApplicationHelp@thelongcenter.org. Program questions: CulturalArts@AustinTexas.gov.', 'https://www.austintexas.gov/arts-culture/funding-programs', null, 'Austin', '2026-08-15', 'starter list'),
  ('acme-live-music-fund', 'Austin Live Music Fund (City of Austin ACME FY27)', 'grant', 'City of Austin ACME FY27', 'A $6 million City of Austin fund for professional musicians, independent promoters, and live music venues.', '["Must meet the Professional Musician, Independent Promoter, or Live Music Venue definition on the program page","Live Music Venue: a minimum $60,000 operating budget","Universal program notes apply: 18 or older, Austin-Round Rock MSA, one application per program per applicant entity"]'::jsonb, '$6 million in total. Professional Musician and Independent Promoter: $20,000 over 24 months or $5,000 over 12 months. Live Music Venue: $70,000 over 12 months.', null, '2026-08-18T18:59:00-05:00', false, 'The FY27 round closed 6:59pm on August 18, 2026. Late applications were not accepted.', 'Complete the Universal Program Eligibility Form, then the program application. Program questions: CulturalArts@AustinTexas.gov.', 'https://www.austintexas.gov/arts-culture/austin-live-music-fund', null, 'Austin', '2026-08-15', 'starter list'),
  ('acme-heritage-preservation', 'Heritage Preservation Grant (City of Austin ACME FY27)', 'grant', 'City of Austin ACME FY27', 'City of Austin funding for heritage events and historic-site projects. KUT reported about $3 million.', '["Heritage events and historic-site projects","Universal program notes apply: Austin-Round Rock MSA, public activities in Austin or the ETJ, one application per program per applicant entity"]'::jsonb, 'About $3 million in total (as reported by KUT)', null, '2026-08-18T18:59:00-05:00', false, 'The FY27 round closed 6:59pm on August 18, 2026. Late applications were not accepted.', 'Complete the Universal Program Eligibility Form, then the program application. Program questions: CulturalArts@AustinTexas.gov.', 'https://www.austintexas.gov/arts-culture/funding-programs', null, 'Austin', '2026-08-15', 'starter list'),
  ('acme-nexus', 'Nexus (City of Austin ACME)', 'grant', 'City of Austin ACME', 'A City of Austin program for emerging cultural and creative individuals and organizations.', '["Emerging cultural and creative individuals and organizations"]'::jsonb, null, null, null, false, 'Listed as opening in September 2026. The exact dates are not in the starter list.', null, 'https://www.austintexas.gov/arts-culture/funding-programs', null, 'Austin', '2026-08-15', 'starter list'),
  ('acme-creative-space', 'Creative Space Assistance Program (City of Austin ACME)', 'other', 'City of Austin ACME', 'Listed on the City of Austin ACME funding page as opening in Summer 2027. The starter list has no other details.', '[]'::jsonb, null, null, null, false, 'Listed as opening in Summer 2027.', null, 'https://www.austintexas.gov/arts-culture/funding-programs', null, 'Austin', '2026-08-15', 'starter list'),
  ('haam', 'HAAM (Health Alliance for Austin Musicians)', 'health', null, 'Health care help for Austin''s working musicians: premium assistance, primary care, dental, vision, hearing, mind and body, fitness, and healthcare navigation.', '["Working musician, music teacher, or DJ (part or full time)","Lives in Travis or surrounding counties","Annual tax household income at or below 400% of the federal poverty level (self-employed: net after expenses)","Proof of music work in the last 12 months (gigs, releases, teaching, and similar). HAAM says apply anyway if unsure."]'::jsonb, null, null, null, true, 'People can join year-round. Open enrollment for insurance help is November 1 to December 15.', 'Request an application on the join page. Contact: 512-541-4226 option 2, support@myhaam.org.', 'https://www.myhaam.org/join-haam', 'https://www.myhaam.org/programs', 'Austin', '2026-08-15', 'starter list'),
  ('twc', 'Texas Workforce Commission (TWC)', 'work', null, 'The state labor agency: unemployment, workforce solutions, training, and benefits for people with uneven work. Someone with a few gigs plus a retail job can still ask.', '["People with uneven work. Specific benefit amounts and eligibility come from TWC and local Workforce Solutions offices."]'::jsonb, null, null, null, true, 'Ongoing. No cycle or deadline.', 'Contact TWC or a local Workforce Solutions office. The starter list does not include benefit amounts.', 'https://www.twc.texas.gov', null, 'Texas', '2026-08-15', 'starter list'),
  ('tca', 'Texas Commission on the Arts (TCA)', 'grant', null, 'The state arts agency. Its grant guidelines and deadline calendar are on its site.', '["See the guidelines for each TCA program."]'::jsonb, null, null, null, false, 'The starter list has no current open cycle. Check the TCA calendar.', null, 'https://www.arts.texas.gov', null, 'Texas', '2026-08-15', 'starter list')
